# Generated: the window Kevin's mods share, taken from Hunter Change's plain window, under Co-op Duel's
# names. Its comments may speak of other mods. Never edited by hand: docs/duel/outils/menu_window.py
# writes this file.
# Generated by sync_menu_ui; edit canonical sources.
"""The sentence at the top of a page, under its title and above its rows, always in view, in an orange slanted frame:
drawn for Apex Heirloom's settings that wait for the next weapon change (Kevin, 2026-09-26, sketch A,
cosmetics/heirloom/docs/esquisses_menu/A.png), and said on the grapple's LOOK page when the grapple gun's look gave way
to the classic one (2026-10-14). Every generated window ships this file, Apex Grapple's (outils/sync_menu_ui.py).

Which page says what is the mod's menu.NOTICES: by page, the key of a text, or a function giving one, or None while
there is nothing to say. The labels write it when the window opens and redraws, in capitals as the sketch did.
"""

from . import menu, panel_i18n as i18n, panel_text as tx, panel_theme as t, panel_widgets as w


def pages():
    """The mod's menu.NOTICES: none in a window whose menu has no such table."""
    return getattr(menu, "NOTICES", {})


def notice(rows, widgets, key):
    frame, fill = w.framed(rows, t.COLOR_CARD, t.STROKE, w.pad(t.SPACE_2, t.SPACE_4), frame=t.COLOR_SPARK)
    widgets[f"notice:{key}"] = tx.text(fill, "", "status", wrap=True)
    fill.SetContent(widgets[f"notice:{key}"])
    # The frame as a whole, for a sentence that comes and goes: hidden, it leaves no empty orange box.
    widgets[f"notice_frame:{key}"] = frame
    w.column(rows, w.slant(frame), padding=w.pad(t.SPACE_3, 0, t.SPACE_1, t.SPACE_1), halign="Left")


def write(widgets, key, language):
    """Page `key`'s sentence, read now: a text key's always shows; a function's frame hides while it gives None."""
    said = pages()[key]
    if callable(said):
        said = said()
        shown = "Collapsed" if said is None else "HitTestInvisible"
        widgets[f"notice_frame:{key}"].SetVisibility(w.enum("ESlateVisibility", shown))
    if said is not None:
        widgets[f"notice:{key}"].SetText(i18n.text(said, language).upper())
